#!/usr/bin/env node
'use strict';

// Launcher for the review-mcp binary. Plain Node, no dependencies.
//
// stdout is the MCP channel, so this file never writes to stdout: every
// message of its own goes to stderr. The child inherits all three standard
// streams, so its output reaches the client byte for byte.
//
// The name of the platform package is derived from this package's own
// package.json (generated by npm/scripts/build-packages.mjs), so the npm
// scope is defined in exactly one place.

const childProcess = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');

const FORWARDED_SIGNALS = ['SIGINT', 'SIGTERM', 'SIGHUP'];

function platformPackageName(mainName, platform, arch) {
  return `${mainName}-${platform}-${arch}`;
}

function binaryFileName(platform) {
  return platform === 'win32' ? 'review-mcp.exe' : 'review-mcp';
}

// A fixed sentence: it names the expected package and nothing from the
// environment except the platform and architecture.
function missingPackageMessage(mainName, platform, arch) {
  const pkg = platformPackageName(mainName, platform, arch);
  return (
    `review-mcp: the platform package "${pkg}" is not installed, ` +
    `so there is no review-mcp binary for ${platform}-${arch}.\n` +
    `Reinstall ${mainName} without --omit=optional (and without --no-optional) ` +
    'so that npm installs the package for your platform.\n'
  );
}

// Returns { path, packaged } or { error }. REVIEW_MCP_BINARY wins when set.
function resolveBinary({ env, platform, arch, mainName, resolve }) {
  if (env.REVIEW_MCP_BINARY) {
    return { path: env.REVIEW_MCP_BINARY, packaged: false };
  }
  const specifier = `${platformPackageName(mainName, platform, arch)}/bin/${binaryFileName(platform)}`;
  try {
    return { path: resolve(specifier), packaged: true };
  } catch {
    return { error: missingPackageMessage(mainName, platform, arch) };
  }
}

// Best effort: some package managers and archive tools drop the execute bit.
function ensureExecutable(file, platform, fsApi) {
  if (platform === 'win32') return;
  try {
    fsApi.accessSync(file, fsApi.constants.X_OK);
  } catch {
    try {
      fsApi.chmodSync(file, 0o755);
    } catch {
      // Ignore: spawn reports the real problem if the file still cannot run.
    }
  }
}

// run starts the binary and wires up signals and the exit status. Every
// dependency is injectable so the tests can use a fake child and a fake
// process object.
function run(opts = {}) {
  const proc = opts.proc || process;
  const spawn = opts.spawn || childProcess.spawn;
  const fsApi = opts.fs || fs;
  const writeErr = opts.writeErr || ((text) => process.stderr.write(text));
  const platform = opts.platform || process.platform;
  const arch = opts.arch || process.arch;
  const env = opts.env || process.env;
  const argv = opts.argv || process.argv.slice(2);
  const mainName = opts.mainName || require('../package.json').name;
  const resolve = opts.resolve || require.resolve;

  const bin = resolveBinary({ env, platform, arch, mainName, resolve });
  if (bin.error) {
    writeErr(bin.error);
    proc.exit(1);
    return;
  }
  if (bin.packaged) ensureExecutable(bin.path, platform, fsApi);

  const child = spawn(bin.path, argv, { stdio: 'inherit' });

  const handlers = FORWARDED_SIGNALS.map((signal) => {
    const handler = () => {
      try {
        child.kill(signal);
      } catch {
        // The child is already gone.
      }
    };
    proc.on(signal, handler);
    return [signal, handler];
  });
  const detach = () => {
    for (const [signal, handler] of handlers) proc.removeListener(signal, handler);
  };

  child.on('error', (err) => {
    detach();
    writeErr(`review-mcp: failed to start the binary (${(err && err.code) || 'unknown error'}).\n`);
    proc.exit(1);
  });

  child.on('exit', (code, signal) => {
    detach();
    if (signal) {
      // Re-raise the child's signal so the parent shell sees the same status.
      proc.kill(proc.pid, signal);
      // Only reached if the signal did not terminate this process.
      const number = (os.constants.signals && os.constants.signals[signal]) || 1;
      setTimeout(() => proc.exit(128 + number), 100);
      return;
    }
    proc.exit(code === null || code === undefined ? 1 : code);
  });
}

module.exports = {
  FORWARDED_SIGNALS,
  platformPackageName,
  binaryFileName,
  missingPackageMessage,
  resolveBinary,
  ensureExecutable,
  run,
};

if (require.main === module) run();
